  concept('actor','foundation',t('Actor','Actor'),t('Papel externo que interactúa con el sistema para conseguir un objetivo.','An external role that interacts with the system to achieve a goal.'),t('Aclara a quién sirve una función y dónde se sitúa el límite del sistema.','It clarifies whom a function serves and where the system boundary lies.'),t('Inicia o participa en un caso de uso desde fuera del límite dibujado.','It starts or participates in a use case from outside the drawn boundary.'),t('Cliente es un actor candidato para la consulta didáctica de Campus Bikes.','Customer is a candidate actor for the Campus Bikes teaching query.'),t('Un actor no tiene que ser una persona concreta.','An actor need not be a specific person.'),['goal','usecase','boundary']);
  concept('goal','foundation',t('Objetivo del actor','Actor goal'),t('Resultado que un actor espera alcanzar al usar el sistema.','An outcome an actor hopes to achieve by using the system.'),t('Evita confundir el propósito del usuario con una pantalla o un botón.','It prevents confusing a user purpose with a screen or button.'),t('Se expresa como una necesidad observable y se relaciona con un caso de uso.','It is expressed as an observable need and related to a use case.'),t('Conocer disponibilidad es el objetivo ilustrativo de la consulta.','Learning availability is the illustrative query goal.'),t('El ejemplo no añade un requisito confirmado al caso oficial.','The example does not add a confirmed requirement to the official case.'),['actor','usecase']);
  concept('usecase','foundation',t('Caso de uso','Use case'),t('Representación de un objetivo que un actor alcanza mediante interacciones con el sistema.','A representation of a goal an actor reaches through interactions with the system.'),t('Relaciona necesidades con capacidades observables antes de diseñar pantallas.','It connects needs to observable capabilities before designing screens.'),t('El actor participa en el escenario y el sistema responde dentro de su límite.','An actor participates in a scenario and the system responds within its boundary.'),t('Consultar disponibilidad sirve como caso de uso ilustrativo.','Check availability serves as an illustrative use case.'),t('Un caso de uso no es una pantalla ni un diagrama de flujo de datos.','A use case is neither a screen nor a data flow diagram.'),['actor','goal','boundary','uml']);
  concept('boundary','foundation',t('Límite del sistema','System boundary'),t('Distinción entre lo que pertenece al sistema modelado y su entorno.','The distinction between the modeled system and its environment.'),t('Evita atribuir al sistema las acciones de sus actores externos.','It avoids assigning external actors’ actions to the system.'),t('En casos de uso, rodea las capacidades del sistema mientras actores permanecen fuera.','In use cases, it encloses system capabilities while actors remain outside.'),t('El Cliente del escenario está fuera; Consultar disponibilidad está dentro del límite ilustrativo.','The scenario Customer is outside; Check availability is inside the illustrative boundary.'),t('El borde visual no establece por sí solo alcance aprobado.','A visual boundary by itself does not establish approved scope.'),['actor','usecase']);

  concept('classdiagram','foundation',t('Diagrama de clases','Class diagram'),t('Vista UML de clases, atributos, operaciones y relaciones estructurales.','A UML view of classes, attributes, operations, and structural relationships.'),t('Permite razonar sobre responsabilidades y vínculos antes de construir la solución.','It allows reasoning about responsibilities and links before building the solution.'),t('Presenta tipos y relaciones con suficiente detalle para revisar el modelo.','It shows types and relationships with enough detail to review the model.'),t('Cliente, Consulta y Bicicleta son clases candidatas ilustrativas de Campus Bikes.','Customer, Query, and Bicycle are illustrative candidate Campus Bikes classes.'),t('No es automáticamente un esquema de tablas ni una implementación.','It is not automatically a table schema or implementation.'),['class','association','operation']);
  concept('association','foundation',t('Relación entre clases','Class relationship'),t('Vínculo estructural significativo entre clases del modelo.','A meaningful structural link between model classes.'),t('Hace visibles dependencias del dominio que deben poder explicarse.','It makes domain dependencies visible so they can be explained.'),t('Se conecta solo cuando su significado y dirección pueden describirse.','It is connected only when its meaning and direction can be described.'),t('Consulta se relaciona con Bicicleta en el ejemplo porque pregunta por ella.','Query relates to Bicycle in the example because it asks about it.'),t('Una línea sin significado no prueba que el vínculo sea válido.','An unexplained line does not prove the link is valid.'),['classdiagram','class']);
