  concept('state','foundation',t('Diagrama de estados','State diagram'),t('Vista de estados de un objeto y de los eventos que provocan cambios.','A view of an object’s states and the events causing change.'),t('Muestra el ciclo de vida del mismo objeto dentro del escenario.','It shows the same object’s lifecycle within the scenario.'),t('Conecta cada estado mediante transiciones justificadas por eventos.','It links states through transitions justified by events.'),t('La Consulta ilustrativa pasa de recibida a en revisión y respondida.','The illustrative Query moves from received to under review to answered.'),t('Los nombres de estado son ilustrativos y no reglas oficiales de Campus Bikes.','The state names are illustrative, not official Campus Bikes rules.'),['scenario','transition','sequence','activity']);
  concept('transition','foundation',t('Transición','Transition'),t('Cambio entre estados provocado por un evento o condición definida.','A change between states caused by a defined event or condition.'),t('Evita que estados parezcan casillas sin explicación de cambio.','It prevents states from looking like boxes with no explanation for change.'),t('Sale de un estado y entra en otro cuando ocurre el evento.','It leaves one state and enters another when its event occurs.'),t('Registrar la consulta inicia la revisión en el ejemplo didáctico.','Recording the query starts review in the teaching example.'),t('Una flecha sola no establece un evento real del negocio.','An arrow alone does not establish a real business event.'),['state','scenario']);
