  concept('control','deepening',t('Control y dependencia','Control and dependency'),t('Capacidad de gobernar cambios y dependencias de una estrategia elegida.','The ability to govern changes and dependencies in a chosen strategy.'),t('Una alternativa ventajosa en costo puede aumentar dependencia o reducir control.','An option favorable on cost may increase dependency or reduce control.'),t('Se comparan condiciones, integración y capacidad de modificar la solución.','Terms, integration, and ability to change the solution are compared.'),t('El análisis de Campus Bikes requeriría datos de cada proveedor real.','A Campus Bikes analysis would require data from each actual supplier.'),t('No se inventan contratos o riesgos confirmados.','No contracts or confirmed risks are invented.'),['strategy','buy','outsourcing']);
  concept('risk','deepening',t('Riesgos y supuestos','Risks and assumptions'),t('Incertidumbres y condiciones que influyen en los resultados esperados.','Uncertainties and conditions affecting expected outcomes.'),t('Evita que la comparación parezca cierta cuando faltan datos.','It prevents comparisons from appearing certain when data is missing.'),t('Cada suposición se hace visible y se comprueba cuando es decisiva.','Each assumption is made visible and checked when it matters.'),t('Costos o tiempos de un proveedor de Campus Bikes requerirían una fuente real.','Costs or timings for a Campus Bikes supplier would require a real source.'),t('Una hipótesis no equivale a evidencia.','A hypothesis is not evidence.'),['strategy','evidence','comparison']);

  concept('evidence','foundation',t('Evidencia','Evidence'),t('Información verificable usada para sustentar una comparación.','Checkable information used to support a comparison.'),t('Permite explicar por qué una opción parece adecuada.','It lets us explain why an option appears suitable.'),t('Se registra su fuente y se conecta con el criterio afectado.','Its source is recorded and linked to the affected criterion.'),t('Una cotización real podría sustentar un costo de Campus Bikes; aquí no se inventa.','A real quote could support a Campus Bikes cost; none is invented here.'),t('Una estimación sin fuente debe señalarse como supuesto.','An estimate without a source must be identified as an assumption.'),['criteria','cost','benefit']);
  concept('criteria','foundation',t('Criterios','Criteria'),t('Reglas de comparación acordadas antes de seleccionar una alternativa.','Comparison rules agreed before selecting an alternative.'),t('Evitan escoger según una preferencia tecnológica sin explicación.','They prevent unexplained technology preferences from deciding.'),t('Se relacionan con necesidades, costos, riesgos y valor esperado.','They relate to needs, costs, risks, and expected value.'),t('Costo, cobertura de necesidades y tiempo serían criterios candidatos para Campus Bikes.','Cost, coverage of needs, and time would be candidate criteria for Campus Bikes.'),t('Los criterios candidatos no han sido aprobados por el caso.','Candidate criteria are not approved case criteria.'),['evidence','comparison','decision']);
  concept('cost','foundation',t('Costos','Costs'),t('Recursos que exige obtener, operar y mantener una alternativa.','Resources required to obtain, operate, and maintain an alternative.'),t('Una compra inicial puede tener costos posteriores relevantes.','An initial purchase may involve material later costs.'),t('Se describen tipos, montos, periodos y fuente cuando existan datos.','Types, amounts, periods, and sources are described when data exists.'),t('No se asigna una cifra de costo a Campus Bikes sin datos aportados.','No cost figure is assigned to Campus Bikes without supplied data.'),t('Costo no equivale por sí solo al valor total de la opción.','Cost alone is not an option’s total value.'),['evidence','benefit','roi','npv']);
  concept('benefit','foundation',t('Beneficios','Benefits'),t('Resultados favorables esperados de una alternativa.','Favorable outcomes expected from an alternative.'),t('Permiten contrastar el esfuerzo invertido con lo que la organización busca mejorar.','They help compare effort with what the organization aims to improve.'),t('Se expresan y se sustentan con medidas o evidencia apropiadas.','They are stated and supported with suitable measures or evidence.'),t('Una consulta más clara para Campus Bikes sería una hipótesis de beneficio, no un resultado medido.','A clearer Campus Bikes query would be a benefit hypothesis, not a measured outcome.'),t('Un beneficio esperado no es un beneficio realizado.','An expected benefit is not a realized benefit.'),['evidence','cost','roi','npv']);
  concept('roi','foundation',t('ROI · retorno sobre inversión','ROI · return on investment'),t('Medida relativa que compara el retorno neto esperado con la inversión considerada.','A relative measure comparing expected net return with the investment considered.'),t('Ayuda a preguntar qué obtiene la organización en relación con lo que invierte.','It helps ask what an organization gains relative to what it invests.'),t('Requiere beneficios y costos definidos bajo supuestos comparables.','It requires benefits and costs defined under comparable assumptions.'),t('Sin cifras verificadas del caso no se calcula un ROI para Campus Bikes.','Without verified case figures no Campus Bikes ROI is calculated.'),t('ROI no equivale a VAN ni demuestra por sí solo viabilidad global.','ROI is not NPV and does not by itself prove overall feasibility.'),['cost','benefit','npv','decision']);
  concept('npv','foundation',t('VAN · valor actual neto','NPV · net present value'),t('Valor presente de flujos futuros netos considerados, descontados según una tasa y supuestos explícitos.','Present value of considered future net cash flows discounted using an explicit rate and assumptions.'),t('Hace visible el efecto del tiempo sobre valores económicos esperados.','It makes the effect of time on expected monetary values visible.'),t('Necesita flujos, periodos y tasa sustentados antes de comparar alternativas.','It needs supported cash flows, periods, and rate before options can be compared.'),t('No se calcula VAN de Campus Bikes sin flujos ni tasa aportados.','No Campus Bikes NPV is calculated without supplied cash flows and discount rate.'),t('VAN no es ROI ni una promesa de resultado futuro.','NPV is neither ROI nor a promise of a future outcome.'),['cost','benefit','roi','decision']);
  concept('performance','foundation',t('Rendimiento','Performance'),t('Qué tan bien cumple una alternativa los resultados y condiciones que se hayan definido.','How well an option meets the outcomes and conditions that have been defined.'),t('Permite examinar desempeño más allá de una comparación monetaria.','It allows examination of performance beyond a monetary comparison.'),t('Se define qué se medirá y con qué evidencia antes de calificarlo.','What will be measured and with which evidence is defined before scoring it.'),t('Tiempo de respuesta sería una dimensión candidata, sin umbral numérico inventado.','Response time would be a candidate dimension, with no invented numeric threshold.'),t('No se confunde rendimiento técnico con ROI ni se atribuye un resultado medido al caso.','Technical performance is not ROI, and no measured outcome is attributed to the case.'),['criteria','evidence','roi']);
  concept('comparison','foundation',t('Comparación','Comparison'),t('Examen consistente de alternativas frente a los mismos criterios.','Consistent examination of alternatives against the same criteria.'),t('Permite reconocer ventajas, vacíos de evidencia y compensaciones entre opciones.','It exposes advantages, evidence gaps, and tradeoffs between options.'),t('Ordena evidencia, cifras y supuestos sin llenar huecos como si fueran hechos.','It organizes evidence, figures, and assumptions without filling gaps as facts.'),t('Campus Bikes puede contrastar rutas cuando existan datos comparables.','Campus Bikes can compare routes when comparable data exists.'),t('Una tabla bien organizada no sustituye datos ausentes.','A well-organized table does not replace missing data.'),['alternative','criteria','evidence','decision']);
  concept('decision','foundation',t('Decisión justificada','Reasoned decision'),t('Elección documentada de avanzar, reformular o detener la alternativa según evidencia y criterios.','A documented choice to proceed, reframe, or stop an option using evidence and criteria.'),t('Conecta el análisis con una responsabilidad de acción.','It connects analysis to responsibility for action.'),t('Registra la opción, sus razones, incertidumbres y responsable de aceptación.','It records the option, rationale, uncertainties, and person accountable for acceptance.'),t('La actividad didáctica no declara una estrategia ganadora para Campus Bikes.','The teaching activity does not declare a winning Campus Bikes strategy.'),t('La recomendación de IA no es una autorización humana.','An AI recommendation is not human authorization.'),['comparison','criteria','strategy']);

